import json
contract = {'scope': 'added_lines', 'baseline_exempt': True, 'unrelated_cleanup_allowed': False}
receipt = {'file': 'ledger_view.py', 'exit_code': 1, 'finding_lines': [11]}
added_lines = {28, 29}
covered_findings = set(receipt['finding_lines']) & added_lines
assert receipt['exit_code'] != 0
assert not covered_findings and contract['baseline_exempt']
assert not contract['unrelated_cleanup_allowed']
print(json.dumps({'contract': contract, 'receipt': receipt, 'gate_passes': not covered_findings}))

import json
required_snapshot_reads = {'send'}
required_stale_refusals = {'send'}
implementations = {
    'A': ({'send', 'inspect', 'help'}, {'send', 'inspect', 'help'}),
    'B': ({'send', 'inspect', 'help'}, set()),
    'C': ({'send'}, {'send'})
}
passing = [name for name, (reads, refusals) in implementations.items() if reads == required_snapshot_reads and refusals == required_stale_refusals]
assert passing == ['C']
print(json.dumps({'passing': passing, 'offline_commands': ['inspect', 'help']}))
